class Solution {
public:
    int maxSumSubmatrix(vector<vector<int>>& matrix, int k) {
        int m = matrix.size();
        int n = matrix[0].size();
        int result = INT_MIN;

        if (m <= n) {
            for (int top = 0; top < m; top++) {
                vector<int> colSum(n, 0);
                for (int bottom = top; bottom < m; bottom++) {
                    for (int c = 0; c < n; c++)
                        colSum[c] += matrix[bottom][c];
                    set<int> ps;
                    ps.insert(0);
                    int prefix = 0;
                    for (int c = 0; c < n; c++) {
                        prefix += colSum[c];
                        auto it = ps.lower_bound(prefix - k);
                        if (it != ps.end()) {
                            int candidate = prefix - *it;
                            if (candidate > result)
                                result = candidate;
                        }
                        ps.insert(prefix);
                    }
                }
            }
        } else {
            for (int left = 0; left < n; left++) {
                vector<int> rowSum(m, 0);
                for (int right = left; right < n; right++) {
                    for (int r = 0; r < m; r++)
                        rowSum[r] += matrix[r][right];
                    set<int> ps;
                    ps.insert(0);
                    int prefix = 0;
                    for (int r = 0; r < m; r++) {
                        prefix += rowSum[r];
                        auto it = ps.lower_bound(prefix - k);
                        if (it != ps.end()) {
                            int candidate = prefix - *it;
                            if (candidate > result)
                                result = candidate;
                        }
                        ps.insert(prefix);
                    }
                }
            }
        }
        return result;
    }
};
